head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vIsuCd = "";
scwin.vIsuNm = "";
scwin.vIsurCd = "";
scwin.vProcsStatCd = "";
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let parentWin = $c.frame.path("../");

        // 업무처리번호
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        // 종목코드
        scwin.vIsuCd = parentWin.clickIsuCd;
        scwin.vIsuNm = parentWin.clickIsuNm;
        scwin.vProcsStatCd = parentWin.clickProcsStatCd;
        txb_ISU_CD.setValue(scwin.vIsuCd);
        txb_ISU_NM.setValue(scwin.vIsuNm);
        const vHeadString = "ITEM:STRING(100),VALUE1:STRING(300),VALUE2:STRING(300),CORRYN:STRING(1)";
        // dts_Log.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        await scwin.listSync(scwin.vIsuCd);
        if (scwin.gJobTitle !== "09") {
            // 팀장이 아닐경우
            btn_Revw.hide();
            btn_Cls.hide();
        } else {
            // 팀장일 경우
            // 상태코드가 34(수정요청) 일 경우에만 승인/반려 가능
            if (scwin.vProcsStatCd !== "34") {
                btn_Revw.setBackgroundImage("../img/btn_BosApv_d.gif");
                btn_Revw.setDisabled(true);
                btn_Cls.setBackgroundImage("../img/btn_BosReject_d.gif");
                btn_Cls.setDisabled(true);
            } else {
                btn_Revw.setBackgroundImage("../img/btn_BosApv.gif");
                btn_Revw.setDisabled(false);
                btn_Cls.setBackgroundImage("../img/btn_BosReject.gif");
                btn_Cls.setDisabled(false);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032P.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        // 닫기(수량변경)
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032P.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        grd_List.Redraw = false;
        // 일치항목 표시
        scwin.setListingData();
        grd_List.redraw = true;
        dts_Log.setRowPosition(1, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032P.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lcd.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032P.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lcd.fn_alertMsg('S');
        // fn_getBaseInfo_read_sync();
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032P.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Cls_onclick
 * @description 「팀장반려」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cls_onclick = async function() {
    try {
        let vAnswer = confirm('반려처리 하시겠습니까?');
        if (vAnswer === true) {
            LastJob = "반려";
            await scwin.trs("37");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032P.btn_Cls_onclick" });
    }
};

/**
 * @method
 * @name btn_Revw_onclick
 * @description 「팀장승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Revw_onclick = async function() {
    try {
        let vAnswer = confirm('승인처리 하시겠습니까?');
        if (vAnswer === true) {
            LastJob = "승인";
            await scwin.trs("35");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032P.btn_Revw_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 상장원부 검토승인
 * @param {String} vSrchIsuCd vSrchIsuCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function(vSrchIsuCd) {
    url += "&ISU_CD=" + vSrchIsuCd;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description 접수 또는 반려처리
 * @param {String} listProcsStatCd listProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(listProcsStatCd) {
    vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    scwin.vBzProcsNo = dts_List.getCellData(1, "BZ_PROCS_NO"); // 업무처리번호
    scwin.vIsuCd = dts_List.getCellData(1, "ISU_CD"); // 종목코드
    scwin.vIsurCd = dts_List.getCellData(1, "LIST_APPLNT_ISUR_CD"); // 상장인 발행기관 코드

    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : TR_JOB_UPDATE,
    //     LD_MKT_TP_CD : "1",
    //     LIST_PROCS_STAT_CD : listProcsStatCd,
    //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     ISU_CD : scwin.vIsuCd,
    //     ISUR_CD : scwin.vIsurCd,
    //     PROCS_EMP_NO : js_emp_no,
    //     ACPT_NO : js_emp_no,
    //     TRANSTR_EMP_NO : js_emp_no
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/digital/DigitalListinvstg.do",
        ref : "dts_List",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sameYn
 * @description 일치여부 확인
 * @param {*} src1 src1
 * @param {*} src2 src2
 * @returns {void}
 * @hidden N
 */
scwin.sameYn = function(src1, src2) {
    if (src1 === "" && src2 === "") {
        return '-';
    } else if (src1 === src2) {
        return 'O';
    } else {
        return 'X';
    }
};

/**
 * @method
 * @name parentRefresh
 * @description Parent 화면 Refresh()
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    // Parent 신청내역 화면 Refresh
    let parentWin = $c.frame.path("../");
    parentWin.fn_list_sync();
};

/**
 * @method
 * @name setItem
 * @description 일반 데이터에 대해 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItem = function(vIdx, strNm, strCd, dtsObj) {
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    if (dtsObj !== "") {
        dts_Log.setCellData(vIdx, 'VALUE1', dtsObj.getCellData(1, strCd));
        dts_Log.setCellData(vIdx, 'VALUE2', dtsObj.getCellData(2, strCd));
        dts_Log.setCellData(vIdx, 'CORRYN', scwin.sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
    }
};

/**
 * @method
 * @name setItemDate2
 * @description 날짜 데이터에 대해 포맷지정 후 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {*} strCd1 strCd1
 * @param {*} strCd2 strCd2
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemDate2 = function(vIdx, strNm, strCd1, strCd2, dtsObj) {
    let date1 = "";
    let date2 = "";
    if (($c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) !== "") && ($c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2)) !== "")) {
        date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2));
    } else if ($c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) !== "") {
        date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1));
    } else {
        date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2));
    }
    if (($c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) !== "") && ($c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2)) !== "")) {
        date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2));
    } else if ($c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) !== "") {
        date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1));
    } else {
        date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2));
    }
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', date1);
    dts_Log.setCellData(vIdx, 'VALUE2', date2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.sameYn(date1, date2));
};

/**
 * @method
 * @name setItemNumber
 * @description 숫자 데이터에 대해 포맷지정 후 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemNumber = function(vIdx, strNm, strCd, dtsObj) {
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    let data1 = $c.stf.FormatNumberEx(dtsObj.getCellData(1, strCd));
    let data2 = $c.stf.FormatNumberEx(dtsObj.getCellData(2, strCd));
    dts_Log.setCellData(vIdx, 'VALUE1', data1);
    dts_Log.setCellData(vIdx, 'VALUE2', data2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};

/**
 * @method
 * @name setItemYyyymm
 * @description 일반 데이터에 대해 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemYyyymm = function(vIdx, strNm, strCd, dtsObj) {
    let ym1 = dtsObj.getCellData(1, strCd);
    let ym2 = dtsObj.getCellData(2, strCd);
    let data1 = "";
    let data2 = "";
    if (ym1.length === 6) {
        data1 = ym1.substring(0, 4) + "-" + ym1.substring(4, 6);
    } else {
        data1 = ym1;
    }
    if (ym2.length === 6) {
        data2 = ym2.substring(0, 4) + "-" + ym2.substring(4, 6);
    } else {
        data2 = ym2;
    }
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', data1);
    dts_Log.setCellData(vIdx, 'VALUE2', data2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.sameYn(ym1, ym2));
};

/**
 * @method
 * @name setItemYymm
 * @description 일반 데이터에 대해 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemYymm = function(vIdx, strNm, strCd, dtsObj) {
    let ym1 = dtsObj.getCellData(1, strCd);
    let ym2 = dtsObj.getCellData(2, strCd);
    let data1 = "";
    let data2 = "";
    if (ym1.length === 4) {
        data1 = ym1.substring(0, 2) + "-" + ym1.substring(2, 4);
    } else {
        data1 = ym1;
    }
    if (ym2.length === 4) {
        data2 = ym2.substring(0, 2) + "-" + ym2.substring(2, 4);
    } else {
        data2 = ym2;
    }
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', data1);
    dts_Log.setCellData(vIdx, 'VALUE2', data2);
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.sameYn(ym1, ym2));
};

/**
 * @method
 * @name setItemDate
 * @description 날짜 데이터에 대해 포맷지정 후 Row 표시
 * @param {*} vIdx vIdx
 * @param {String} strNm strNm
 * @param {String} strCd strCd
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setItemDate = function(vIdx, strNm, strCd, dtsObj) {
    dts_Log.setCellData(vIdx, 'ITEM', strNm);
    dts_Log.setCellData(vIdx, 'VALUE1', $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd)));
    dts_Log.setCellData(vIdx, 'VALUE2', $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd)));
    dts_Log.setCellData(vIdx, 'CORRYN', scwin.sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};

/**
 * @method
 * @name setListingData
 * @description set Listing Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setListingData = function() {
    const totItemCnt = 72;
    dts_Log.setBroadcast(false);
    for (let j = 1; j <= totItemCnt; j++) {
        dts_Log.insertRow();
    }
    dts_Log.setBroadcast(true, true);
    let i = 1;
    scwin.setItem(i++, '발행증권에 관한 사항', '', '', '');
    scwin.setItem(i++, '한글종목명', 'ISU_KOR_NM', dts_List);
    scwin.setItem(i++, '한글종목약명', 'ISU_KOR_ABBRV', dts_List);
    scwin.setItem(i++, '영문종목명', 'ISU_ENG_NM', dts_List);
    scwin.setItem(i++, '영문종목약명', 'ISU_ENG_ABBRV', dts_List);
    scwin.setItem(i++, '종목코드', 'ISU_CD', dts_List);
    scwin.setItem(i++, '단축코드', 'ISU_SRT_CD', dts_List);
    scwin.setItemNumber(i++, '상장수량', 'LIST_QTY', dts_List);
    scwin.setItemNumber(i++, '공모가액', 'PUBOFR_AMT', dts_List);
    scwin.setItemNumber(i++, '상장총액', 'LIST_AMT', dts_List);
    scwin.setItem(i++, '증권 구분', 'SECUGRP', dts_List);
    scwin.setItem(i++, '상장신청인', 'LIST_APPLNT_ISUR_NM', dts_List);
    scwin.setItem(i++, '지정자문인', 'DESIGN_ADVSER_ISUR_NM', dts_List);
    scwin.setItemDate2(i++, '지정자문인 계약기간', 'DESIGN_ADVSER_CONTRT_STRT_DD', 'DESIGN_ADVSER_CONTRT_END_DD', dts_List);
    scwin.setItem(i++, '기초자산(종류)', 'DIGITAL_SECU_ULY_CD', dts_List);
    scwin.setItem(i++, '기초자산(명)', 'DIGITAL_SECU_ULY_NM', dts_List);
    scwin.setItem(i++, '신탁기관', 'TRST_INST_ISUR_NM', dts_List);
    scwin.setItemDate2(i++, '신탁기관 계약기간', 'TRST_CONTRT_PD_STRT_DD', 'TRST_CONTRT_PD_END_DD', dts_List);
    scwin.setItem(i++, '위탁/보관기관', 'TRST_CUSTDN_NM', dts_List);
    scwin.setItemDate2(i++, '위탁/보관기관 계약기간', 'TRST_CUSTDN_STRT_DD', 'TRST_CUSTDN_END_DD', dts_List);
    scwin.setItem(i++, '수익자명부관리 대행기간', 'BENF_NMLIST_ADM_AGNT_NM', dts_List);
    scwin.setItem(i++, '의무보유 확약여부', 'DUTY_HD_CMIT_YN', dts_List);
    scwin.setItem(i++, '의무보유자', 'DUTY_HD_NM', dts_List);
    scwin.setItemNumber(i++, '의무보유수량', 'DUTY_HD_CNT', dts_List);
    scwin.setItemDate2(i++, '의무보유기간', 'DUTY_HD_STRT_DD', 'DUTY_HD_END_DD', dts_List);
    scwin.setItemDate(i++, '의무보유해제일', 'DUTY_HD_RELEAS_DD', dts_List);
    scwin.setItem(i++, '유동성공급/분배에 관한사항', '', '', '');
    scwin.setItem(i++, '유동성공급자 계약체결여부', 'LP_CONTRT_TRD_YN', dts_List);
    scwin.setItem(i++, '유동성공급자I', 'LP_MBR_NO1_NM', dts_List);
    scwin.setItemDate2(i++, '유동성공급자I 계약기간', 'LP_CONTRT_STRT_DD', 'LP_CONTRT_END_DD', dts_List);
    scwin.setItem(i++, '유동성공급자II', 'LP_MBR_NO2_NM', dts_List);
    scwin.setItemDate2(i++, '유동성공급자I 계약기간', 'LP_CONTRT_STRT_DD2', 'LP_CONTRT_END_DD2', dts_List);
    scwin.setItem(i++, '유동성공급자III', 'LP_MBR_NO3_NM', dts_List);
    scwin.setItemDate2(i++, '유동성공급자III 계약기간', 'LP_CONTRT_STRT_DD3', 'LP_CONTRT_END_DD3', dts_List);
    scwin.setItem(i++, '신종증권분배금형태', 'DIGITAL_SECU_DISTR_TP', dts_List);
    scwin.setItemYymm(i++, '분배금 기준일1', 'DISTR_PAY_BAS_DD', dts_List);
    scwin.setItemYymm(i++, '분배금 기준일2', 'DISTR_PAY_BAS_DD2', dts_List);
    scwin.setItemYymm(i++, '분배금 기준일3', 'DISTR_PAY_BAS_DD3', dts_List);
    scwin.setItemYymm(i++, '분배금 기준일4', 'DISTR_PAY_BAS_DD4', dts_List);
    scwin.setItemYymm(i++, '분배금 기준일5', 'DISTR_PAY_BAS_DD5', dts_List);
